INSERT INTO `answers` VALUES (1,1000,1,NULL,'你是奶龙吗','2025-03-08 02:58:00',1),(2,1001,1,1,'你才是奶龙','2025-03-08 02:58:51',1),(3,1000,1,2,'风风光光了','2025-03-08 03:10:49',1),(4,1001,1,3,'消息测试','2025-03-08 03:21:02',1),(5,1002,1,NULL,'什么时候带我上荣耀','2025-03-08 03:57:33',1),(6,1001,1,NULL,'时区测试','2025-03-10 06:50:34',0),(7,1001,1,NULL,'时区测试','2025-03-10 06:51:37',0),(8,1001,1,NULL,'时区测试','2025-03-10 07:04:05',0),(9,1001,1,NULL,'时区测试\r\n','2025-03-10 15:04:50',0),(10,106,2,NULL,'那是相当好用又好看','2025-03-12 01:03:35',2),(11,1001,5,NULL,'确实很长','2025-03-14 14:29:07',0),(12,106,6,NULL,'目前只有两级的保研数据：20 级为 28.57%，21 级为 29.17%','2025-03-18 02:53:26',1),(13,106,30,NULL,'是的，维持原专业不变','2025-03-18 07:34:01',0),(14,106,29,NULL,'我们目前能有完整数据的只有 20 级，他们去年刚毕业。20 级的总体深造率在 60%','2025-03-18 07:35:58',0),(15,106,28,NULL,'人工智能学院有很多偏硬件、偏机器人的人工智能方向。我们学院的人工智能方向会更多地与软件开发这个环节相关','2025-03-18 07:39:25',0),(16,106,25,NULL,'挂科得补考、或重修，通过之后会影响这门课的成绩计算，会打折低一点。但不会影响后续的保研、奖学金一类的资格问题','2025-03-18 07:41:33',0),(17,106,27,NULL,'我知道还是有不少同学对专业知识始终不感兴趣，或者自认没有能力学好。那么我们至少会有一段学习经历，对计算机领域的知识会熟悉一些。目前这类同学大多会去信息类的但没那么知名的公司，比如 20 级同学有几位去了普联。信息类关联更少的也有，比如宝洁管培生','2025-03-18 07:56:30',0),(18,106,25,16,'补充一下，辅导员周老师更正我了，挂科会影响奖学金评定，只是不影响保研资格的认定','2025-03-19 02:33:53',0),(19,106,33,NULL,'现在这个时代，绩点可以选择放弃，但科研/工程已经是必选项，不能不卷了，不然毕业之后毫无竞争力。目前的措施是让大家认清现实，并且给卷科研/工程的同学一个制度上的保障。不能一边让大家卷新的，一边又用老的卷绩点的评价手段。','2025-03-20 01:09:43',0),(20,127,4,NULL,'Hello hello～','2025-03-20 01:17:59',0),(21,106,23,NULL,'当然，学院各位老师很卷。建院四年以来，老师们依靠大量的科研产出成功地把CSRankings 卷成了野榜，无论是同行还是同学们都表示难以接受中大软件工程位于全球前列。','2025-03-20 01:20:21',1),(22,106,39,NULL,'补考通过之后没有影响','2025-03-20 15:18:03',0),(23,128,47,NULL,'程序设计考C语言，笔试','2025-04-18 04:54:26',0),(24,128,49,NULL,'希望你对编程充满兴趣，并在兴趣的驱使下自己主动地有所作为，或主动学习知识，或动手写点东西','2025-04-18 04:57:09',0),(25,128,53,NULL,'1、高数一考上册，不考下册\r\n2、程序设计考c语言\r\n3、笔试','2025-04-18 04:59:04',0),(26,128,50,NULL,'考核时间还没具体确定，初试计划安排在5月10或11日，以最后通知为准，请提前复习。初试考高数一上册和C语言，都是笔试。','2025-04-18 07:09:49',0),(27,128,59,NULL,'程序设计主要考概念和语法，不需要手写完整的程序','2025-04-21 01:21:09',0),(28,128,61,NULL,'根据课程修读情况和考核情况确定接收年级，也会综合考虑个人意愿，不会强制降级。','2025-04-22 07:12:01',0),(29,128,60,NULL,'程序设计只考C语言，软件工程学院的程序设计II课程学的是C++','2025-04-22 07:14:27',0),(30,128,63,NULL,'同学你好，相比原专业背景，我们更看重同学的学习能力、思维潜力以及对软件工程专业的热情与适配度。往年也有接收其他不同学科背景的同学，只要对软件工程专业怀有热忱、在考核中表现出色，都是有机会的','2025-04-23 02:58:03',0),(31,128,64,NULL,'同学你好，面试没有要求用英文，一般包括\r\n自我介绍、随机抽取试题回答，面试官根据情况进一步提问','2025-04-23 03:02:13',0),(32,128,65,NULL,'程序设计考的是C语言，当然希望你掌握得越扎实，越能展现优势。面试主要看是否对编程有热情、是否有认真学习的态度和迎难而上的勇气。如果仅仅是因为听闻计算机专业就业薪资可观，而对计算机领域缺乏基本认知和兴趣，恐怕难以在面试中获得高分。毕竟，缺乏兴趣不了解，转进来也容易陷入痛苦，不仅难以学好，未来的职业发展也可能受到影响。\r\n原绩点占比不高，毕竟要求同学在不感兴趣的专业中仍保持优异成绩，本身就存在一定矛盾。如对自己的原绩点没有信心，可以在面试过程中进行合理说明解释。','2025-04-23 03:38:34',0),(33,128,66,NULL,'同学你好，目前最新的本科学籍管理规定细则是没有这方面的限制的。我们本次转专业接收年级是2024级和2025级的','2025-04-24 03:36:00',0),(34,128,83,NULL,'可以的','2025-04-27 04:57:32',0),(35,128,93,NULL,'每位考生面试时间约10分钟。包括：\r\n（1）考生自我介绍3分钟；\r\n（2）考生随机抽取试题回答；\r\n（3）考官根据考生情况进一步提问','2025-04-30 02:06:25',0),(36,127,120,NULL,'可以的，争取下周发问卷收集家长观礼的信息，不过因为毕业大会场地最多容纳差不多500人，所以会设置报名上限。','2025-05-29 11:19:21',0),(37,127,121,NULL,'如果当前阶段是入党积极分子，那毕业时候会把入党材料给回学生本人，你去到下一个单位或者学校，可以问问对方负责党务的工作人员，看看在软工的培养材料能不能沿用。','2025-05-29 11:21:02',0),(38,127,122,NULL,'这个我是很清楚，双证发放要咨询两位教务老师，按去年的情况，差不多是在6.21左右。','2025-05-29 11:22:07',0),(39,127,123,NULL,'两个问题的回答都是“可以”，如果确实有特殊情况不能参加学院毕业大会，可以钉钉联系我说明；退宿可以跟宿管确认能不能代办，前提是你宿舍里的东西已经清理干净、水电费已经结算等。','2025-05-29 11:23:40',0),(40,1000,1,NULL,'11','2025-06-06 12:27:04',0),(41,1056,38,NULL,'不知道为什么不能问老师？报错请求无响应，提问失败。\r\n\r\n草稿好像会保存多次，即使是一样的','2025-06-14 07:51:14',0),(42,128,129,NULL,'今年软工学院广东省计划招生76人，可以参考2024年最低录取分为645分，省排3777名，2023年最低分651分，省排3859名。','2025-06-22 01:51:43',0),(43,128,130,NULL,'目前就读软件工程专业的同学大部分在高中时都没有编程基础和经验。进入大学之后，只要愿意多实践，在不断地编程练习中体验成就感，进而激发出学习的兴趣，软件工程专业学习起来就不会困难。','2025-06-22 01:53:02',0),(44,128,131,NULL,'软工2024届的保研率为28.57%，2025届保研率为29.17%，保研学校有北大，复旦，浙大，上交大，中科大，哈工大，中大等','2025-06-22 02:00:06',0),(45,128,132,NULL,'除了公共基础课程高等数学、线性代数、概率论、离散数学、大学物理之外，软件工程专业的核心基础课程包括程序设计、数据结构与算法、计算机组成原理、操作系统原理、计算机网络、数据库系统原理、编译原理、软件工程实训等。经过循序渐进的编程练习之后，各门课程均可以较好地掌握。','2025-06-22 02:04:47',0),(46,1013,38,NULL,'从别的网站跳到这个网站里，click返回按钮返回到原本的网站去了🤔','2025-07-19 14:57:53',0),(47,1001,38,46,'一般情况下返回是直接回到上一个页面🤔看起来是合理的。可以提供更多信息嘛，直接邮件发给我就好','2025-07-31 09:56:29',0),(48,1001,38,41,'请问现在还是这样吗，是提问的哪个老师呢，草稿这个我们现在看看','2025-07-31 09:58:00',0),(49,1036,1,NULL,'1','2025-09-16 05:34:24',0),(50,1036,1,49,'2','2025-09-16 05:36:48',0),(51,1036,1,40,'邮件测试','2025-09-16 05:38:48',0),(52,1036,1,NULL,'3','2025-09-16 05:39:27',0),(53,1000,1,51,'111','2025-09-16 07:35:45',0),(54,106,133,NULL,'基础系统开发的优化有两个标准的路径：1、接口的自动化测试；2、寻求高并发测试和优化。在有限资源下冲击更高的并发访问量。','2025-11-07 06:13:13',0),(55,128,134,NULL,'我院培养方案里面的程序设计I是3学分理论+1学分实验课，内容为C语言；程序设计II是2学分理论+1学分实验，内容为C++。专业课成绩转换遵循以下原则：申请转换的课程需与对应课程教学大纲相近，且学分不低于培养方案中该课程的学分。','2026-02-02 02:16:40',0),(56,127,135,NULL,'你们大二从南校迁回珠海校区，学校分配的宿位是按各个院系分别给的，所以不能跟其他学院的同学拼宿舍哦','2026-02-06 06:40:42',0),(57,128,139,NULL,'22级大四下学期还有三门公必课：形势与政策3学分，国家安全教育1学分，劳动教育1学分，一门专必课：毕业论文6学分','2026-03-17 07:44:28',0),(58,127,140,NULL,'25级本科搬迁回珠海校区前，会发布相关通知让大家重新组宿舍，原则上在同班级内进行组合，考虑到每个班女生人数较少，女生可以跨一个班级。','2026-03-24 02:48:36',0),(59,128,143,NULL,'同学你好，程序设计考C语言，笔试','2026-04-13 03:41:57',0),(60,128,144,NULL,'可以留空哈','2026-04-13 07:03:27',0),(61,128,145,NULL,'课程教学大纲相近，学分大于等于我们培养方案上的课程是可以申请成绩转换的','2026-04-14 00:48:55',0),(62,128,146,NULL,'和去年不会相差很大，不用手写完整代码','2026-04-14 00:50:18',0),(63,128,147,NULL,'有的','2026-04-14 00:50:46',0);
