/*!40000 ALTER TABLE `teachers` DISABLE KEYS */;
INSERT INTO `teachers` VALUES (100,0,'郑子彬','https://suask.me/upload/teachers/郑子彬.jpg','郑子彬，教授、博导、IEEE Fellow、IET Fellow、ACM杰出科学家、全球高被引科学家、国家优秀青年科学基金获得者、国家数字家庭工程技术研究中心副主任、广东省区块链工程技术研究中心主任。发表论文多篇，论文谷歌学术引用超过37,000次，H指数为89。主持国家重点研发计划项目、自然科学基金重点项目等多个项目；获得教育部自然科学二等奖、 吴文俊人工智能自然科学二等奖、 ACM中国新星提名奖、IEEE TCSVC Rising Star Award、CCF服务计算专委会杰出青年奖、ACM SIGSOFT Distinguished Paper Award、ICWS最佳学生论文奖等奖项；担任TOSEM、TSC、TVT、OJCS等期刊的副编辑；担任ICSS2022、IEEE SMDS2021、BlockSys2019、CollaborateCom 2016等会议的General Co-Chair；担任ICSOC2023、SC22019、教师简介: \n郑子彬，教授、博导、IEEE Fellow、IET Fellow、ACM杰出科学家、全球高被引科学家、国家优秀青年科学基金获得者、国家数字家庭工程技术研究中心副主任、广东省区块链工程技术研究中心主任。发表论文多篇，论文谷歌学术引用超过37,000次，H指数为89。主持国家重点研发计划项目、自然科学基金重点项目等多个项目；获得教育部自然科学二等奖、 吴文俊人工智能自然科学二等奖、 ACM中国新星提名奖、IEEE TCSVC Rising Star Award、CCF服务计算专委会杰出青年奖、ACM SIGSOFT Distinguished Paper Award、ICWS最佳学生论文奖等奖项；担任TOSEM、TSC、TVT、OJCS等期刊的副编辑；担任ICSS2022、IEEE SMDS2021、BlockSys2019、CollaborateCom 2016等会议的General Co-Chair；担任ICSOC2023、SC22019、ICIOT2018 及IoV2014等会议的PC Co-Chair。\n研究领域: \n软件可靠性，程序分析，区块链，智能合约，可信软件。\n本科、硕士和博士招生：常年欢迎报名。 及IoV2014等会议的PC Co-Chair。','zhzibin@mail.sysu.edu.cn','private'),(101,0,'余阳','https://suask.me/upload/teachers/余阳.jpg','余阳，博士，教授，博士生导师。国家数字家庭工程技术研究中心副主任，软件技术广东普通高校重点实验室主任。中国计算机学会（CCF）杰出会员，ACM会员，CCF协同计算专委会执行委员，广东省高性能计算学会理事，广东省软件工程教学指导委员会副主任。','yuy@mail.sysu.edu.cn','private'),(102,0,'王国利','https://suask.me/upload/teachers/王国利.jpg','王国利，工学博士，教授，德国洪堡基金获得者。\n邮箱：isswgl@mail.sysu.edu.cn\n研究领域：普适计算、泛在感知与泛在智能\n教育背景：1982年至1992年期间在南开大学学习，于1986年、1989年和19992年分获南开大学理学学士、理学硕士和工学博士学位。\n工作经历：1992年至2003年期间在汕头大学工作，期间担任计算机系系主任，1999年晋升教授。2003年11月起受聘中山大学信息科学与技术学院教授和博士导师，曾分别担任自动化系系主任、信息科学与技术学院副院长。2016年至2023年受聘计算机学院，曾任智能科学与技术研究所所长、机器智能与先进计算教育部重点实验室主任。\n获奖及荣誉：分别获得汕头市先进劳动者称号、教育部科学奖励自然科学二等奖和广东省科学奖励自然科学二等奖、中国人工智能学会智能空天专委会 “杰出贡献奖”。\n学术兼职：目前担任中国系统仿真学会智能物联系统专业委员会副主任委员、广东省机械工程学会/自动化学会机器人与智能制造分会副理事长。\n科研项目：入职中山大学以来，持续不间断获得国家自然科学基金项目资助6项，目前主持在研项目1项。','isswgl@mail.sysu.edu.cn','private'),(103,0,'王若梅','https://suask.me/upload/teachers/王若梅.jpg','王若梅，教授，博士生导师，国家数字家庭工程技术研究中心副主任。主持国家重点研发计划、国家自然科学基金、国家科技2030重大专项（中大负责人）等一批重点科研项目和课题，理论方法创新方面的成果发表在顶级的学术期刊，获得国家教育部科技进步一等奖；广州市科技进步二等奖；广东省高教厅科技进步二等奖；广东省科技进步三等奖，国家科技进步二等奖，2022年教育部科技进步二等奖。','isswrm@mail.sysu.edu.cn','private'),(104,0,'周育人','https://suask.me/upload/teachers/周育人.jpg','周育人，博士，教授，博士生导师。\n邮箱：zhouyuren@mail.sysu.edu.cn\n主要研究方向为算法设计与分析、演化算法等。\n教育背景：1988年本科毕业于北京大学数学专业，2003年在武汉大学获计算机软件与理论专业博士学位。2007年—2008年美国加州大学尔湾分校访问学者。\n在国际国内计算机科学、软件工程重要刊物“Artificial Intelligence” 、“ACM Transactions on Software Engineering and Methodology ”、 “IEEE Transactions on Evolutionary Computation”、“IEEE Transactions on Cybernetics”等发表了多篇相关学术论文， 近年来承担国家、省部级项目多项。','zhouyuren@mail.sysu.edu.cn','private'),(105,0,'陈武辉','https://suask.me/upload/teachers/陈武辉.jpg','陈武辉，软件工程学院教授，博士生导师，珠海市可信大模型重点实验室主任。入选广东省“珠江人才计划”青年拔尖人才项目、广东省“珠江人才计划”引进创新创业团队核心成员。承担国家重点研发计划课题、国家自然科学基金面上和青年项目等多个国家级省部级项目，以及来自华为、百川智能、华东院、广州金融科技、招联消费金融等多个校企合作项目，部分成果得到落地应用。成果发表在EuroSys、NDSS、SoCC、Infocom、VLDB、ICDE、IEEE TPDS、IEEE TC、IEEE TDSC等知名会议和期刊上，获吴文俊人工智能自然科学二等奖、CCF B类会议IEEE ICPP 2020最佳论文亚军奖。出版Springer著作《Blockchain Scalability》。目前担任国际期刊 International Journal of Systems and Service-Oriented Engineering主编。入选全球前 2% 顶尖科学家榜单。','chenwuh@mail.sysu.edu.cn','private'),(106,11,'苏玉鑫','https://suask.me/upload/teachers/苏玉鑫.jpg','苏玉鑫 (B站ID：鸭大坑导)，软件工程学院副院长，副教授，博士生导师，国家重点研发计划青年科学家项目负责人，中国计算机学会（CCF）高级会员、服务计算专委会执行委员。2021年7月入选中山大学百人计划，加入软件工程学院。主要研究方向为系统软件可靠性分析与运行时性能优化，具体包括操作系统、分布式系统、云计算、云原生系统、日志分析、云系统可靠性与智能运维(AIOps)等。近年来在国际会议和期刊共发表近30篇论文，其中24篇发表于ICSE、ASE、ISSTA、SOSP、FAST、ICDE、CVPR、SIGIR、AAAI、IJCAI、CSUR、TKDE等软件工程、操作系统、分布式系统、人工智能等领域CCF A类顶级会议与期刊。','suyx35@mail.sysu.edu.cn','public'),(107,0,'李丹','https://suask.me/upload/teachers/李丹.jpg','李丹，副教授，硕士生导师，2021年2月入选中山大学百人计划青年学术骨干，加入软件工程学院。2018年至2021年于新加坡国立大学担任研究员，从事博士后研究工作。2013年至2017年就读于新加坡南洋理工大学，受新加坡与加州大学伯克利分校联合项目资助，获得博士学位。2008年至2012年就读于电子科技大学，获得学士学位。主要从事信息物理融合系统，工业互联网，预测性维护，时序数据分析，大模型垂域应用等方面的研究。目前于IEEE TII、IEEE TASE、Energy Build. ICDE等国际著名期刊和会议上发表20余篇论文。','lidan263@mail.sysu.edu.cn','private'),(108,0,'毛明志','https://suask.me/upload/teachers/毛明志.jpg','毛明志，博士，中山大学副教授，硕士生导师。中国计算机学会（CCF）杰出会员，全国高校计算机研究会理事，CCF教育专委会执行委员,《软件导刊》和《软件工程与应用》编委和审稿人，广东省科协荣誉工作者。长期从事高等学校计算机与软件工程专业相关的教学和研究工作，获国家科学技术进步二等奖、中山大学卓越服务奖和中国高校计算机教育大会优秀论文一等奖（2021）。','mcsmmz@mail.sysu.edu.cn','private'),(109,0,'南雨宏','https://suask.me/upload/teachers/南雨宏.jpg','南雨宏，副教授，硕士生导师。中山大学百人计划青年学术骨干，校青年拔尖人才。曾任美国普渡大学(Purdue University)计算机系博士后研究员，普渡CERIAS访问学者。博士毕业于复旦大学。博士期间曾获国家留学基金委资助，于美国印第安纳大学布卢明顿分校(Indiana University Bloomington)进行联合培养。\n主要研究方向为系统软件安全及隐私保护。包括面向大模型、移动互联网生态、智能合约等平台的研究。研究成果发表于USENIX Security、ACM CCS，NDSS, ICSE, FSE，ASE, ISSTA等系统安全及软件工程领域顶级会议。主持国家自然科学基金、广东省新一代电子信息（半导体）重点领域专项、广东省自然科学基金（面上项目）等省部级项目，曾作为科研骨干参与国家 973 计划、美国政府及企业资助的多项研究。目前担任广东省区块链工程技术研究中心智能合约安全研发负责人，CCF珠海委员。担任ACM CCS 2024, ACM/IEEE ASE 2024, ASIACCS 2021, 2022, ICICS 2021, 2022等国际会议程序委员会委员。担任IEEE TIFS, TDSC, TOPS，TMC, TSE，EMSE等期刊审稿人。研究发现的安全及隐私问题多次获得来自Google、Meta (Facebook)、X (Twitter)、Slack、国内三大电信运营商（移动、联通、电信）等厂商的官方确认及致谢。','nanyh@sysu.edu.cn','private'),(110,0,'黄袁','https://suask.me/upload/teachers/黄袁.jpg','黄袁，博士/博士后，副教授，博士生导师。主持国家重点研发计划子任务，国家自然科学基金青年项目，博士后面上项目（一等资助），广东省基金面上项目等。以项目骨干身份参与国家重点研发计划，国家基金重点项目，广东省重点研发计划等多个项目。2017年于中山大学获得博士学位，从事软件工程相关研究，重点关注软件缺陷与代码智能等研究方向。近年来在IEEE Transactions on Software Engineering, ACM Transactions on Software Engineering and Methodology, IEEE Transactions on Services Computing, FSE/ESEC, ASE, ICSE等软件工程领域CCF A/B期刊及会议上发表论文40余篇。同时担任多个国际期刊和会议的审稿人。获“2024优秀硕士学位论文指导教师”奖项。','huangyuan5@mail.sysu.edu.cn','private'),(111,0,'陈建国','https://suask.me/upload/teachers/陈建国.jpg','陈建国，副教授，硕士生导师，中山大学百人计划青年学术骨干。湖南大学计算机科学与技术博士，美国伊利诺伊大学联合培养博士，曾任加拿大多伦多大学博士后，新加坡A*STAR科技研究局研究科学家。目前主要研究方向是分布式并行计算、分布式人工智能、联邦计算、计算机视觉、图计算及应用。\n目前在IEEE-TII、IEEE-TITS、IEEE-TPDS、IEEE-TKDE、IEEE/ACM-TCBB、ACM-TIST、ACM-TCPS等国际著名期刊和会议上发表学术论文50余篇。主持国家自然科学基金青年项目、博士后国际交流计划派出项目、广东省自然科学基金面上项目、湖南省自然科学基金青年项目等项目。作为科研骨干先后曾参与国家高技术研究发展计划（863计划）、国家重点基础研究发展计划（ 973 计划）等多项科研课题项目。担任国际学术期刊《International Journal of Embedded Systems》副主编、《Journal of Current Scientific Research》副主编、《Information Sciences》客座编辑、《Neural Computing and Applications》客座编辑，以及多个国际学术会议的技术委员会成员。','chenjg33@mail.sysu.edu.cn','private'),(112,0,'吴嘉婧','https://suask.me/upload/teachers/吴嘉婧.jpg','吴嘉婧，中山大学副教授，博士生导师。入选广东省重大人才工程、Elsevier全球前2%顶尖科学家榜单。现任ACM-中国珠海分会副主席，广东省区块链工程技术研究中心副主任，IEEE和中国计算机学会高级会员，中国计算机学会 (CCF) 区块链专委会执行委员、服务计算专委会执行委员。\n2014年于香港理工大学获博士学位，随后入职中山大学计算机学院，2023年8月调入中山大学软件工程学院。研究方向包括区块链数据监管与反欺诈、Web3、智能合约、复杂网络、图挖掘等。 主持国家重点研发计划课题、子课题，国家自然科学基金面上（2项）、青年项目，和企业横向（蚂蚁集团、招联金融等）等项目十余项。已在ISSTA、WWW、IEEE Trans. Software Engineering, IEEE Trans. Information Forensics and Security, IEEE Transactions on Systems, Man, and Cybernetics: Systems等A类或一区的国际学术期刊和会议上发表论文80余篇，其中IEEE Transactions论文50余篇，ESI高被引论文4篇。在Springer 出版区块链英文学术著作 3 部。组织团队同学负责区块链数据共享平台Xblock的开发与设计 www.xblock.pro。','wujiajing@mail.sysu.edu.cn','private'),(113,0,'黄华威','https://suask.me/upload/teachers/黄华威.jpg','黄华威，中山大学副教授，软件工程学院 “区块链与可信软件研究中心” 副主任，广东省杰青，从2023年起连续入选年度全球前 2% 科学家榜单，IEEE Senior Member，中国计算机学会 (CCF) 高级会员。研究方向包括高性能区块链系统、Web3 基础设施与协议、DeFi 协议、分布式基础设施网络 (DePIN) 等。多篇研究成果发表在 CCF A 类期刊 ToN, JSAC, TPDS, TDSC, TMC, TC 等，以及 CCF A 类国际会议 INFOCOM。论文谷歌引用 6500+, H-index 34。曾担任十余个国内外学术会议论坛研讨会的主席。主持国家重点研发计划课题、国自然面上青年项目、广东省普通高校重点领域专项、CCF-华为胡杨林基金区块链专项、鹏城实验室区块链项目等十余项科研项目。出版区块链英文学术著作 2 部《From Blockchain to Web3 & Metaverse》与《Blockchain Scalability》，出版区块链科普书《从区块链到Web3：构建下一代互联网生态》；带领团队开源区块链实验平台 BlockEmulator，该平台为区块链方向的研究生提供了成熟优质的实验平台，可快速迭代出新成果。','huanghw28@mail.sysu.edu.cn','private'),(114,0,'何笑雨','https://suask.me/upload/teachers/何笑雨.jpg','何笑雨，副教授，硕士生导师，中山大学百人计划青年学术骨干。博士毕业于中山大学。先后在中山大学和南洋理工大学从事博士后研究工作。智能优化方法及其在人工智能和控制论中的应用，包括\n演化学习方法：机器学习、联邦学习、数据挖掘的演化计算求解方法\n人工智能的底层优化问题：同步/异步并行优化、面向大数据的随机优化、流形优化、多目标/多层次优化等\n智能控制方法：演化多智能体系统、强化学习的黑盒策略搜索','hexy73@mail.sysu.edu.cn','private'),(115,0,'孔树锋','https://suask.me/upload/teachers/孔树锋.jpg','孔树锋，副教授，硕士生导师，中山大学百人计划青年学术骨干。2018年10月毕业于澳大利亚悉尼科技大学工程与信息技术学院，获博士学位。分别于美国加州大学尔湾分校 (2017.11—2018.05) 、美国康奈尔大学 (2018.10—2020.09) 和新加坡南洋理工大学 (2020.10—2022.08) 从事科研工作, 并于2022年9月加盟中山大学软件工程学院。本人的研究内容主要包括多智能体系统、深度学习、强化学习、自动推理与规划、约束优化、Computational Sustainability、AI for Scientific Discovery（particularly in materials science, biology, and agriculture)、多标签分类、多目标回归、大语言模型等。本人目前已在Nature Communications、NeurIPS、ICML、AAAI、IJCAI、CP和AAMAS等国际顶尖期刊和会议上发表学术论文20余篇，并参与国内外重大科研项目多项。本人长期担任多个期刊和会议（NeurIPS、ICML、ICLR、AAAI、IJCAI和TNNLS等）的审稿人。本人亦长期与康奈尔大学Carla Gomes教授团队(https://www.cs.cornell.edu/gomes/) 、南洋理工大学安波教授团队(https://personal.ntu.edu.sg/boan/) 和悉尼科技大学李三江教授团队（https://profiles.uts.edu.au/Sanjiang.Li） 保持良好合作关系。 另外个人主页请参见 (https://sk2299.github.io)。欢迎有意向合作的单位或个人来信联系，也欢迎有意攻读我院研究生的同学或有意来中山大学从事博士后工作的同仁与我联系','kongshf@mail.sysu.edu.cn','private'),(116,0,'蒋子规','https://suask.me/upload/teachers/蒋子规.jpg','蒋子规，副教授，硕士生导师，中国计算机学会（CCF）服务计算专委会执行委员。2015-2019就读于北京邮电大学网络与交换技术国家重点实验室，获得博士学位，并获北京邮电大学优秀博士学位论文、北京市优秀毕业生等荣誉。2019年入职中山大学计算机学院从事博士后研究工作，2020年调入中山大学软件工程学院。主要研究方向包括区块链数据分析、智能合约、代码推荐与补全、推荐算法、大数据分析、用户行为分析等。承担包括国家自然科学基金、博士后站前特别资助、广东省自然科学基金、山东省自然科学基金智慧计算联合基金以及企业横向等项目。近年来在国内外权威学术期刊与会议上发表论文二十余篇，并担任BlockSys2023/2020/2019、CollaborateCom 2022/2016、IEEE Services 2020、IEEE SCC 2016、ICCSA 2016等国际会议的组织者、审稿人和Session Chair，以及IEEE TSC、IEEE TCC、IEEE ACCESS、ACM TSAS等多个国际期刊的审稿人。','jiangzg3@mail.sysu.edu.cn','private'),(117,0,'刘名威','https://suask.me/upload/teachers/刘名威.jpg','刘名威，副教授，博士生导师，中山大学“逸仙学者计划”新锐学者，中国计算机学会（CCF）软件工程专委会执行委员。2024年6月加入软件工程学院，此前在复旦大学获得本科学位（2017年）、博士学位（2022年）并完成博士后研究（2024年）。\n研究聚焦于软件工程（SE）与人工智能（AI）交叉领域，特别是在AI4SE和SE4AI方面。我的主要兴趣在于利用先进的AI技术，如大规模语言模型（LLM）和知识图谱（KG），解决软件工程中的挑战，并应对AI应用和场景中常见的软件工程和系统工程问题。具体研究方向包括但不限于基于大模型的智能化开发与维护、软件开发知识图谱、大模型可信评测、可信代码大模型等。近五年来，在软件工程领域顶级国际期刊和会议（如TSE、TOSEM、ICSE、FSE、ASE等）发表了20余篇论文，并荣获多项殊荣，包括IEEE TCSE杰出论文奖（ICSME 2018，CCF-B）和ACM SIGSOFT杰出论文奖（FSE 2023，CCF-A）。更多信息请见个人主页：https://mingwei-liu.github.io/。','liumw26@mail.sysu.edu.cn','private'),(118,0,'娄坚','https://suask.me/upload/teachers/娄坚.jpg','娄坚，副教授，博士生导师。曾于美国埃默里大学(Emory University)从事博士后研究工作。主要研究方向包括可信人工智能、可信大模型、人工智能隐私保护、数据隐私保护、数据质量评估等。近年在NeurIPS、ICCV、CVPR、SIGMOD、VLDB、WWW、ACM CCS、IEEE S&P、NDSS、TDSC等人工智能、数据库、安全与隐私保护领域的顶会顶刊上发表论文60余篇，并获得顶会ACM CCS 2024杰出论文奖(ACM SIGSAC Distinguished Paper Award)，IEEE/WIC/ACM WI-IAT 2020最佳理论论文奖(Best in Theoretical Paper Award)等，研究成果曾获国际知名科技媒体New Scientist采访报道。担任人工智能顶会ICML领域主席、AAAI资深程序委员，安全与隐私保护顶会ACM CCS程序委员，数据库顶会VLDB程序委员。','louj5@mail.sysu.edu.cn','private'),(119,0,'廖国成','https://suask.me/upload/teachers/廖国成.jpg','廖国成，助理教授，硕士生导师。2021年4月入选中山大学百人计划，加入软件工程学院。2021年于香港中文大学信息工程系获得博士学位；2019 于加州理工学院进行交流访问；2016年于中山大学电子与信息工程学院获学士学位。主要研究方向为边缘计算、算力网络、联邦学习、隐私保护、群智感知、物联网、网络优化。主持国自然青基和广东省面上项目。近年来的工作多发表于国际顶级会议和期刊，包括 CCF A 类期刊ACM/IEEE Trans. on Networking','liaogch6@mail.sysu.edu.cn','private'),(120,0,'吴炜滨','https://suask.me/upload/teachers/吴炜滨.jpg','吴炜滨，中山大学“百人计划”助理教授，硕士生导师，中国计算机学会软件工程专业委员会执行委员。2021年于香港中文大学计算机科学与工程学系获得博士学位，师从ACM/IEEE/AAAS Fellow 吕荣聪教授与IEEE Fellow 金国庆教授。2017年于同济大学电子与信息工程学院获得学士学位。主要研究方向包括可信人工智能、深度学习、计算机视觉、自然语言处理、智能软件工程等，重点关注深度学习（智能软件）的可靠性、安全性、可解释性与隐私性。主持或参与国家自然科学基金、香港研资局、深圳科创委等多个基金项目。为多个国际顶级会议和期刊的审稿人，如AAAI、ICLR、ICCV、ECCV、ACL、EMNLP、TKDE等。近年来在NeurIPS、CVPR、FSE等人工智能、计算机视觉、软件工程领域的顶级会议上发表论文16篇。','wuwb36@mail.sysu.edu.cn','private'),(121,0,'陈嘉弛','https://suask.me/upload/teachers/陈嘉弛.jpg','陈嘉弛，中山大学“百人计划”助理教授，硕士生导师。2022年于澳大利亚蒙纳士大学获得博士学位，主要研究方向包括软件可靠性、智能合约安全、Web3安全、大模型技术及应用、代码分析、智能合约、经验软件工程等，重点关注大模型技术在代码分析上的应用、漏洞挖掘、区块链。近5年在软件工程领域四大顶会及两大顶刊发表论文30余篇，并获得3次ACM SIGSOFT Distinguished Best Paper, 3次Best Paper Award。','chenjch86@mail.sysu.edu.cn','private'),(122,0,'陈文清','https://suask.me/upload/teachers/陈文清.jpg','陈文清，中山大学“百人计划”助理教授，硕士研究生导师，博士毕业于上海交通大学电子信息与电气工程学院、人工智能研究院，师从金耀辉教授。主要研究方向包括自然语言处理、大语言模型、代码智能、智慧医疗、智慧司法等，目前研究兴趣集中在大语言模型的复杂推理。主持纵向项目包括国自然青年基金、广东省面上项目、人工智能教育部重点实验室开放课题；主持两项大模型横向课题；参与国家重点研发计划、上海市级科技重大专项资助、上海市人工智能创新发展专项资助、上海市科技计划等多个基金项目。在人工智能领域、自然语言处理国际权威期刊及会议发表论文20+篇，获国家发明专利授权6项。担任多个国际顶级会议和期刊的审稿人，如ACL、EMNLP、IJCAI、AAAI、 Expert Syst App.等。','chenwq95@mail.sysu.edu.cn','private'),(123,0,'王焱林','https://suask.me/upload/teachers/王焱林.jpg','王焱林，助理教授，硕士生导师。2022年7月入选中山大学百人计划，加入软件工程学院。加入中山大学前，于微软亚洲研究院担任主管研究员。2014年至2019年就读于香港大学计算机科学系，师从Bruno Oliveira教授，获得博士学位。2010年至2014年就读于浙江大学，获学士学位。主要研究方向为大模型驱动的智能化软件工程、大模型技术。近5年来在国际会议和期刊共发表30余篇论文，发表于ICSE、ASE、AAAI、ACL、KDD、TKDE、EMSE、EMNLP、CIKM、ICSME等软件工程、人工智能、自然语言处理等领域CCF A/B类顶级会议与期刊。','wangylin36@mail.sysu.edu.cn','private'),(124,0,'陈壮彬','https://suask.me/upload/teachers/陈壮彬.jpg','陈壮彬，助理教授，硕士生导师，中国计算机学会（CCF）服务计算专委会执行委员。2023年1月入选中山大学百人计划，加入软件工程学院。2018年至2022年，于香港中文大学计算机科学与工程系攻读博士学位，师从ACM/IEEE/AAAS Fellow吕荣聪（Michael R. Lyu）教授。主攻研究领域为大型智能软件系统，包括云计算、机器学习、软件可靠性、智能运维、数据中心网络等方面。近年来，在ICSE、FSE、ASE、DSN、CIKM、ACM Computing Surveys、Information Sciences等软件工程、数据挖掘、计算机网络领域的CCF A类顶级会议和期刊发表论文20余篇。','chenzhb36@mail.sysu.edu.cn','private'),(125,0,'潘茂林','https://suask.me/upload/teachers/潘茂林.jpg','潘茂林，中山大学软件工程学院教师。','panml@mail.sysu.edu.cn','private'),(126,0,'王乐球','https://suask.me/upload/teachers/王乐球.jpg','王乐球，硕士，中山大学软件工程学院专任教员。\n教育背景：\n1987-1991，浙江大学计算机软件学士\n1991-1994浙江大学计算机应用硕士\n工作情况：\n1994-1999珠海远方电脑公司从事软件开发\n1999-2001珠海电力工业局工作\n2001-2020中山大学资讯管理学院\n2020-至今，软件工程学院','isswlq@mail.sysu.edu.cn','private'),(127,7,'周玉婷','https://suask.me/upload/teachers/周玉婷.jpg','周玉婷，本硕均毕业于中山大学，现任软件工程学院党政专职辅导员，负责学生工作、宣传工作，曾获“中山大学新生军训优秀指导员”“中山大学优秀辅导员”等称号。','zhouyt69@mail.sysu.edu.cn','public'),(128,24,'蓝晓婵','https://suask.me/upload/teachers/蓝晓婵.jpg','蓝晓婵，中山大学软件工程学院本科教务秘书，负责协助学院做好制定本科专业培养方案、本科教学计划、教学大纲等本科教学发展性工作，负责本科教学教务管理、学籍管理、考务管理等教学日常管理工作，协助全程导师组织管理工作，保障本科生实践教学顺利开展。','lanxch3@mail.sysu.edu.cn','public'),(129,0,'林柱良','https://suask.me/upload/teachers/林柱良.jpg','林柱良，负责学院党务工作、共青团工作','linzhliang6@mail.sysu.edu.cn','public'),(130,0,'李桐','https://suask.me/upload/teachers/李桐.jpg','李桐，研究生秘书，负责研究生招生、教务工作','litong73@mail.sysu.edu.cn\n\n','public');
